// Calculation accuracy, end to end: inputs typed into the real page, numbers read
// off the real cards, compared with tests/e2e/fixtures/expected.json, which is
// generated by tests/reference/e2e_expected.py from the published program rules
// (never from the app's code). See that file for every rule's source.
//
// What this adds over the unit tests: input handling, effects (price resets
// escrow), URL parameters, layout wiring and formatting, in both layouts.
import { test, expect } from "./support/test";
import { CalculatorPage, PROGRAMS, type Program } from "./support/calculator";
import { readFileSync } from "node:fs";

type Expected = {
  eligible: boolean;
  reason?: string;
  rate?: string;
  total?: string;
  pi?: string | null;
  mi?: string | null;
  miLabel?: string | null;
  upfront?: string | null;
  upfrontLabel?: string | null;
  baseLoan?: string | null;
  totalLoan?: string | null;
  ambiguous?: string[];
  knownDefect?: { id: string; correct: { miLabel: string; mi: string; total: string }; app: { miLabel: string; mi: string; total: string } };
};
type Scenario = { id: string; title: string; price: number; downPct: string; term: 15 | 30; rates: Record<Program, string>; vaUsage: string; taxes: number; insurance: number; url?: string; expected: Record<Program, Expected> };

const { scenarios } = JSON.parse(readFileSync(new URL("./fixtures/expected.json", import.meta.url), "utf8")) as { scenarios: Scenario[] };
export const scenario = (id: string) => scenarios.find((s) => s.id === id)!;

// Fill every input of a scenario through the UI.
async function enter(calc: CalculatorPage, s: Scenario) {
  await calc.set({ price: s.price, downPct: s.downPct, term: s.term, rates: s.rates, taxes: s.taxes, insurance: s.insurance });
}

// Compare every eligible card with the reference. A documented known defect is
// asserted as today's behavior, with the correct value attached to the report.
async function expectCards(calc: CalculatorPage, s: Scenario) {
  for (const program of PROGRAMS) {
    const e = s.expected[program];
    if (!e.eligible) {
      await expect(calc.card(program), `${program} card`).toContainText("Ineligible");
      await expect(calc.card(program)).toContainText(e.reason!);
      continue;
    }
    const shown = e.knownDefect ? e.knownDefect.app.total : e.total!;
    if (e.knownDefect) {
      test.info().annotations.push({
        type: "known-defect",
        description: `${e.knownDefect.id}: ${program} shows ${e.knownDefect.app.total} (${e.knownDefect.app.miLabel}); correct per source is ${e.knownDefect.correct.total} (${e.knownDefect.correct.miLabel})`,
      });
    }
    await expect(calc.total(program), `${program} monthly total`).toHaveText(shown);
    await expect(calc.rateField(program), `${program} rate`).toHaveValue(e.rate!);
  }
  await calc.expectNoBrokenNumbers();
}

test.describe("calculation accuracy against the independent reference", () => {
  test("A1: default scenario, every program's monthly total", async ({ page }) => {
    const calc = new CalculatorPage(page);
    await calc.open();
    await enter(calc, scenario("A1"));
    await expectCards(calc, scenario("A1"));
  });

  test("A1: breakdown lines for every program add up to the reference", async ({ page }) => {
    const s = scenario("A1");
    const calc = new CalculatorPage(page);
    await calc.open();
    await enter(calc, s);
    for (const program of PROGRAMS) {
      const e = s.expected[program];
      const scope = await calc.breakdown(program);
      const check = async (label: string, field: keyof Expected) => {
        if (e[field] == null || e.ambiguous?.includes(field)) return; // see e2e_expected.py
        await expect(calc.row(scope, label), `${program} ${label}`).toHaveText(e[field] as string);
      };
      await check("Principal & Interest", "pi");
      if (e.miLabel) await check(e.miLabel, "mi");
      if (e.upfrontLabel) await check(`+ ${e.upfrontLabel}`, "upfront");
      await check("Base Loan Amount", "baseLoan");
      await check("Total Loan Amount", "totalLoan");
      await expect(calc.row(scope, "Taxes")).toHaveText("$300");
      await expect(calc.row(scope, "Insurance")).toHaveText("$100");
    }
  });

  test("A2: settings arrive in the link; the rate in the link applies to FHA only", async ({ page }) => {
    const s = scenario("A2");
    const calc = new CalculatorPage(page);
    await calc.open(s.url);
    await expect(page.getByLabel("Home Price", { exact: true })).toHaveValue("400,000");
    await expect(page.getByLabel("Loan Term")).toHaveValue("15");
    await expectCards(calc, s); // FHA 6.000 from the link; the others from the rate feed
  });

  test("A4: at 0% interest, principal and interest is the loan divided by 360", async ({ page }) => {
    const s = scenario("A4");
    const calc = new CalculatorPage(page);
    await calc.open();
    await enter(calc, s);
    await expectCards(calc, s);
    const conv = await calc.breakdown("Conventional");
    await expect(calc.row(conv, "Principal & Interest")).toHaveText(s.expected.Conventional.pi!); // $288,000 / 360
  });

  test("D-6 characterization: a high-balance FHA loan uses the standard MIP rate", async ({ page }) => {
    const s = scenario("D6");
    const calc = new CalculatorPage(page);
    await calc.open();
    await enter(calc, s);
    await expectCards(calc, s);
    const fha = await calc.breakdown("FHA");
    // Today: "MIP (0.5%)". HUD ML 2023-05: 0.70% for a base loan over $726,200 at 90% LTV.
    await expect(fha.getByText(s.expected.FHA.knownDefect!.app.miLabel, { exact: true })).toBeVisible();
  });
});
